package com.example.expensetracker.messaging.event;

import com.example.expensetracker.expense.Category;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;

/**
 * Published to the "expense-events" topic every time an expense is saved.
 *
 * Design rules I followed for events:
 *  - eventId is a UUID generated by the producer. Consumers use it as an idempotency key,
 *    because Kafka guarantees at-least-once, not exactly-once, delivery.
 *  - The event is a fact about the past ("ExpenseCreated"), not a command ("SendEmail").
 *    That means new consumers (analytics, ML, audit) can subscribe later without the producer
 *    changing a single line.
 *  - It is a record = immutable. An event that can be mutated in flight is a bug factory.
 */
public record ExpenseCreatedEvent(
        String eventId,
        Long expenseId,
        Long userId,
        String userEmail,
        BigDecimal amount,
        Category category,
        LocalDate spentAt,
        LocalDateTime occurredAt
) {}
